import { MakeLogicType, afterMount, kea, path, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { listAllEvaluationReports } from '../evaluations/evaluationsApi'
import type { EvaluationReportApi } from '../generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface aiObservabilitySelfDrivingLogicValues {
    evaluationReports: EvaluationReportApi[] | null
    evaluationReportsByEvaluationId: Record<string, EvaluationReportApi> | null
    evaluationReportsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface aiObservabilitySelfDrivingLogicActions {
    loadSelfDrivingEvaluationReports: () => any
    loadSelfDrivingEvaluationReportsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadSelfDrivingEvaluationReportsSuccess: (
        evaluationReports: EvaluationReportApi[],
        payload?: any
    ) => {
        evaluationReports: EvaluationReportApi[]
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface aiObservabilitySelfDrivingLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        evaluationReportsByEvaluationId: (
            evaluationReports: EvaluationReportApi[] | null
        ) => Record<string, EvaluationReportApi> | null
    }
}

export type aiObservabilitySelfDrivingLogicType = MakeLogicType<
    aiObservabilitySelfDrivingLogicValues,
    aiObservabilitySelfDrivingLogicActions,
    Record<string, any>,
    aiObservabilitySelfDrivingLogicMeta
>

export const aiObservabilitySelfDrivingLogic = kea<aiObservabilitySelfDrivingLogicType>([
    path(['products', 'ai_observability', 'selfDriving', 'aiObservabilitySelfDrivingLogic']),

    loaders({
        evaluationReports: [
            null as EvaluationReportApi[] | null,
            {
                loadSelfDrivingEvaluationReports: async () => {
                    const teamId = teamLogic.values.currentTeamId
                    return teamId ? await listAllEvaluationReports(teamId.toString()) : []
                },
            },
        ],
    }),

    selectors({
        evaluationReportsByEvaluationId: [
            (selectors) => [selectors.evaluationReports],
            (reports: EvaluationReportApi[] | null): Record<string, EvaluationReportApi> | null =>
                reports
                    ? Object.fromEntries(
                          reports.filter((report) => !report.deleted).map((report) => [report.evaluation, report])
                      )
                    : null,
        ],
    }),

    afterMount(({ actions }) => {
        actions.loadSelfDrivingEvaluationReports()
    }),
])
